/**
 * When a Schedule triggers. Exactly one canonical spelling per shape: a single
 * ISO instant (`at`), a seconds interval re-anchored on each trigger
 * (`every`), or a cron expression with optional IANA timezone (`cron`).
 * Sub-minute rates belong to `every`; calendar points belong to `cron`.
 */
export type SchedulerRecurrence =
  | { at: string }
  | { every: number }
  | { cron: string; timezone?: string };

/**
 * What a Schedule does when it triggers. A closed union so an `append` kind
 * can be added later; the only kind today is running an itx script — a
 * function-expression string invoked as `fn(itx, schedule, trigger)` with
 * project-root itx authority.
 */
export type SchedulerAction = {
  kind: "itx-script";
  /** A function-expression string, invoked as `fn(itx, schedule, trigger)`. */
  script: string;
};

/**
 * A stored secret's public face — its live state and what `__describe()`
 * merges in: usage audit counters, pinned egress URLs, whether material is
 * present, and the configured refresh strategy's kind. Never the material
 * itself: material is write-only and projected away before crossing the RPC
 * boundary.
 */
export type SecretDescription = {
  audit: {
    lastUsedAt?: string;
    lastUsedBy?: string;
    lastUsedUrl?: string;
    usedCount: number;
  };
  egress: { urls: string[] };
  /** Whether the secret processor has reduced its birth certificate. */
  created: boolean;
  hasMaterial: boolean;
  /** How the material may leave (a birth-certificate fact): write-only secrets refuse reveal(). */
  visibility: SecretVisibility;
  /** The configured refresh strategy's kind, or null when none is configured. */
  refresh: SecretRefresh["kind"] | null;
};

/** Encrypted current-value snapshot used only by the admin project-seed CLI. */
export type SecretProjectSeedExport = {
  egressUrls: string[];
  encrypted: {
    algorithm: string;
    ciphertext: string;
    iv: string;
  };
  offset: number;
  refresh: SecretRefresh | null;
  visibility: SecretVisibility;
};

/** Input to `itx.secrets.get(path).create` — the birth policy (egress pin,
 * visibility, refresh strategy) plus optional initial material. */
export type SecretCreateInput = {
  /** Complete egress policy established by the birth certificate. */
  egress: { urls: string[] };
  /** Optional initial write-only material. */
  material?: unknown;
  /** Optional initial refresh strategy; omitted means no refresh. */
  refresh?: SecretRefresh | null;
  /**
   * How the material may leave: "write-only" (never — the default and the
   * classic secret invariant) or "readable" (reveal() answers it, as often
   * as asked). IMMUTABLE: declared at birth, never updatable, so a
   * write-only secret can never be retro-flipped readable. Readable and
   * substitutable are mutually exclusive: a readable secret must have (and
   * keep) an empty egress pin — create and update both reject egress
   * origins on one. Reserve "readable" for credentials whose whole purpose
   * is to be shown to the outside — the born project ingress key at
   * /secrets/project-api-key is the canonical case.
   */
  visibility?: SecretVisibility;
};

/** Input for replacing secret material or changing its egress and refresh policy. */
export type SecretUpdateInput =
  | {
      /** Replacement material must name its complete egress policy in the same
       * authorized update. It never inherits a policy chosen by a public event. */
      egress: { urls: string[] };
      /** Any serializable value (write-only, one JSON blob). A plain string keeps
       * the whole-material placeholder working; structured material is addressed
       * by `field` in placeholders (design §2.1). */
      material: unknown;
      /** A named refresh strategy the secret runs in trusted DO code when a
       * substituted request 401s (or a referenced field is missing), or `null` to
       * clear it. Omitted leaves the strategy unchanged. */
      refresh?: SecretRefresh | null;
    }
  | {
      /** Replaces the effective egress origins. Every update without `material`
       * clears stored material, including egress-only and refresh-only updates. */
      egress?: { urls: string[] };
      material?: never;
      /** Omitted leaves the strategy unchanged. A refresh-only update still
       * clears material because it does not contain replacement material. */
      refresh?: SecretRefresh | null;
    };

/**
 * One repo file mutation.
 *
 * Kept named because public `Repo.commitFiles`, input parsing, and artifact
 * commit implementation all validate the same command shape.
 */
export type RepoFileChange =
  | {
      path: string;
      content: string;
    }
  | {
      path: string;
      /** Standard base64 of the file's raw bytes — the binary write lane
       * (images, PDFs, …), matching the `files.put` string convention. */
      contentBase64: string;
    }
  | {
      path: string;
      delete: true;
    };

/** One commit in a repo's history, as returned by `repo.log`. */
export type RepoLogCommit = {
  oid: string;
  /** Full commit message, trailing newline trimmed. */
  message: string;
  author: { email: string; name: string };
  /** Author timestamp in epoch milliseconds. */
  timestamp: number;
  /** Parent commit oids — empty for the root commit, 2+ for merges. */
  parents: string[];
};

/** One changed file in a commit — `git diff --numstat`-shaped counts. */
export type RepoCommitFileChange = {
  path: string;
  status: "added" | "deleted" | "modified";
  /** Lines added; 0 for binary files. */
  additions: number;
  /** Lines removed; 0 for binary files. */
  deletions: number;
  /** True when either side of the diff sniffs binary (NUL byte). */
  binary: boolean;
};

/**
 * The GitHub repository a repo is linked to: the named GitHub connection (an
 * App installation) whose token authenticates mirror pushes, its installation
 * id, and the owner/repo coordinates on GitHub.
 */
export type GithubRepoLink = {
  connection: string;
  installationId: string;
  owner: string;
  repo: string;
  /** GitHub's stable database identity for this repository. */
  repositoryId: number;
};

/**
 * Stateless workers are WorkerEntrypoint exports loaded directly from source.
 *
 * `props` are passed to `worker.getEntrypoint(name, { props })` and appear as
 * `this.ctx.props` inside the exported WorkerEntrypoint. They deliberately live
 * only on stateless refs: Durable Object facets are started with
 * `ctx.facets.get(name, () => ({ class, id? }))`, which does not accept
 * WorkerEntrypoint-style props.
 */
export type StatelessDynamicWorkerRef = DynamicWorkerRefBase & {
  type: "stateless";
  entrypoint?: string;
  props?: Record<string, JsonValue>;
};

/**
 * Stateful workers are Durable Object class exports hosted by
 * `StatefulWorkerDurableObject`.
 *
 * `durableWorkerKey` is the durable identity under `{ projectId, path }`. It is
 * not a source cache key: source changes deliberately affect the next use of the
 * same durable worker identity.
 */
export type StatefulDynamicWorkerRef = DynamicWorkerRefBase & {
  type: "stateful";
  className: string;
  durableWorkerKey: string;
};

/** One stored overlay: the fields it deviates from (or adds over) the derived table. */
export type WorkspaceMountOverlay = WorkspaceConfig["mounts"][string];

/** The workspace processor's reduced state: existence plus the merged overlays. */
export type WorkspaceProcessorState = {
  birthCertificate: { [x: string]: unknown } | null;
  config: {
    mounts: Record<
      string,
      { policy?: "commit-to-main" | "read-only" | undefined; repoPath?: string | undefined }
    >;
  };
};

/**
 * The workspace's LIVE configuration: the effective mount table that routes
 * reads and commits — every project repo at its own /repos/** stream path
 * (commit-to-main), with the workspace's stored overlay deviations merged in.
 */
export type WorkspaceEffectiveConfig = {
  mounts: Record<
    string,
    {
      policy: "commit-to-main" | "read-only";
      repoPath: string;
    }
  >;
};

/** A configuration patch: deep-merged per mount point; null clears an overlay.
 * (Spelled as one z.output<> reference — not an indexed access over it — so
 * the itx-api generator expands it structurally instead of copying the
 * expression verbatim into the generated public API.) */
export type WorkspaceConfigPatch = {
  mounts?:
    | Record<
        string,
        {
          policy?: "commit-to-main" | "read-only" | undefined;
          repoPath?: string | undefined;
        } | null
      >
    | undefined;
};

/** Input to `Workspace.edit` — a safe single-occurrence string replacement. */
export type EditWorkspaceFileInput = {
  newString: string;
  oldString: string;
  path: string;
  replaceAll?: boolean;
};

/** Result of `Workspace.edit`. The change is in the working tree only — not committed. */
export type EditWorkspaceFileResult = {
  occurrenceCount: number;
  path: string;
};

/** Durable state reduced from the events in one stream. */
export type CoreProcessorState = {
  projectId?: string | null | undefined;
  path?: string | undefined;
  streamId?: string | undefined;
  createdAt?: string | undefined;
  incarnationId?: string | undefined;
  eventCount: number;
  maxOffset: number;
  childPaths: string[];
  paused: boolean;
  pauseReason: string | null;
  circuitBreaker: {
    availableTokens: number;
    lastRefillAtMs: number | null;
    burstCapacity: number;
    refillRatePerMinute: number;
    trippedAtOffset: number | null;
  };
  subscriptions: {
    inbound: {
      bySourcePath: Record<
        string,
        Record<
          string,
          {
            streamId: string;
            streamCreatedAt: string;
            cursorChangedAtSourceOffset: number;
            numEventsReceived: number;
            lastEventReceivedAt?: string | undefined;
          }
        >
      >;
    };
    outbound: {
      byKey: Record<
        string,
        {
          configuration: {
            description?: string | undefined;
            filter?:
              | { eventTypes?: string[] | undefined; jsonataCondition?: string | undefined }
              | undefined;
            receiver:
              | {
                  action: "processor-wake";
                  expression: ItxExpression;
                  processorSlug?: string | undefined;
                }
              | {
                  action: "copy-to-stream";
                  receivingStreamPath: string;
                  jsonataTransform?: string | undefined;
                  delivery: { start: "beginning" | "now"; onFailingEvent: "halt" };
                }
              | {
                  action: "itx-call";
                  expression: ItxExpression;
                  jsonataTransform?: string | undefined;
                  delivery: { start: "beginning" | "now"; onFailingEvent: "halt" | "skip" };
                }
              | {
                  action: "webhook-post";
                  url: string;
                  jsonataTransform?: string | undefined;
                  delivery: { start: "beginning" | "now"; onFailingEvent: "halt" | "skip" };
                };
            subscriptionKey: string;
          };
          configuredAtOffset: number;
          configuredAt: string;
          subscriptionKeyWasGenerated?: true | undefined;
          cursorSet?: { afterOffset: number; setAtSourceOffset: number } | undefined;
          deliveryHalted?:
            | {
                reason: "delivery-failed";
                afterOffset: number;
                attempts: number;
                error?: string | undefined;
              }
            | undefined;
        }
      >;
    };
  };
};

/** Serializable debug view of one live callback connection. */
export type ConnectionRuntimeState = ConnectionRuntimeDetails &
  (
    | { kind: "session" }
    | {
        kind: "hosted";
        /** The durable subscription whose processor callback this connection serves. */
        subscriptionKey: string;
      }
  );

/** Serializable debug view of one stored subscription's cursor row, for `runtimeState()`. */
export type SubscriptionRuntimeState = {
  /** Exclusive. Source-owned acknowledged offset or hosted processor's last reported checkpoint. */
  acknowledgedOffset: number;
  /** `maxOffset - acknowledgedOffset`, per subscription. */
  lag: number;
  attempt: number;
  nextAttemptAt: number | null;
  inFlightDeadlineAt: number | null;
  lastError: string | null;
  /** Serialized payload bytes delivered by copy, ITX-call, and webhook subscriptions. */
  bytesSent?: number;
  /** Commit-to-acked latency (stream clock): newest event `createdAt` → awaited delivery resolved. */
  completionLatencyMs?: LatencyStats;
  /** Duration of the awaited copy, ITX, or webhook call itself. */
  deliveryDurationMs?: LatencyStats;
};

/** What a stream runtime snapshot reports for the stream's own throughput. */
export type StreamThroughputMetrics = {
  /** ISO timestamp when this incarnation started measuring (metrics reset on eviction). */
  measuredSince: string;
  /** ISO timestamp anchoring the trailing windows and final series bucket. */
  reportedAt: string;
  /** Appends committed (all producers). */
  ingress: ThroughputReport;
  /** Event batches sent to all receiving streams and open callbacks. */
  egress: ThroughputReport;
};

/**
 * Batch delivered to stream processors and live connections.
 *
 * Kept named because callback retention, processor hosts, and tests all depend
 * on the same cross-RPC batch envelope.
 */
export type StreamEventBatch = {
  projectId: string | null;
  path: string;
  /** Random identity of this event log; changes when the stream is recreated. */
  streamId: string;
  events: StreamEvent[];
  /** Exclusive raw-log cursor from which this delivery scan began. */
  scannedAfterOffset: number;
  /** Inclusive raw-log cursor through which this delivery scan completed. */
  scannedThroughOffset: number;
  streamMaxOffset: number;
  /** Reduced core state, or null when the connection opts out with `state: false`. */
  state: unknown;
};

/**
 * The mutual ping's request half (NTP-style, for real latency measurement
 * between a stream and its callback owners): the requester stamps `t0` on its own
 * clock and observes `t3` when the reply lands.
 */
export type StreamPingInput = { t0: number };

/**
 * The mutual ping's reply half: the responder echoes `t0` and reports when it
 * received the request (`t1`) and sent the reply (`t2`) on ITS clock.
 * `rtt = (t3 - t0) - (t2 - t1)` excludes responder processing time, and
 * `((t1 - t0) + (t2 - t3)) / 2` estimates the responder−requester clock
 * offset (see stream-runtime-metrics.pingRoundTrip). Purely observational:
 * ping failures drop the sample and never affect delivery or liveness.
 */
export type StreamPingReply = { t0: number; t1: number; t2: number };

/** Stable identity for one live connection to a processEventBatch callback. */
export type ConnectionKey = string;

/** Internal hosted-processor frame: an ordinary batch plus its one-shot completion callback. */
export type StreamWakeEventBatch = StreamEventBatch & {
  reportDeliveryResult: ReportStreamWakeDeliveryResult;
};

/** `StreamEventInput` with `type`/`payload` narrowed to one event definition. */
type TypedStreamEventInput<Type extends string = string, Payload = Record<string, unknown>> = Omit<
  StreamEventInput,
  "payload" | "type"
> & {
  type: Type;
  payload: Payload;
};

/** Input to the Images capability's `transform`: the source image stream,
 * ordered transform steps, optional overlay draws (watermarks — each with its
 * own transforms), and the output encoding. */
export type CfImageTransformInput = {
  image: ReadableStream<Uint8Array>;
  transforms?: CfImageTransformOptions[];
  draws?: Array<{
    image: ReadableStream<Uint8Array>;
    options?: CfImageDrawOptions;
    transforms?: CfImageTransformOptions[];
  }>;
  output: CfImageOutputOptions;
};

/** Input to the videos capability's `transform`: the source video stream,
 * optional transform options, and the output selection. */
export type CfVideoTransformInput = {
  video: ReadableStream<Uint8Array>;
  transform?: CfVideoTransformOptions;
  output: CfVideoOutputOptions;
};

/** A sandbox's size tier ("lite" | "basic" | "standard-1"…"standard-4") —
 * Cloudflare container instance-type names, fixed at `create` and immutable
 * for the sandbox's lifetime. See {@link SANDBOX_INSTANCE_TYPES} for the
 * vCPU/memory/disk table. */
export type SandboxInstanceType =
  | "basic"
  | "lite"
  | "standard-1"
  | "standard-2"
  | "standard-3"
  | "standard-4";

/** How a secret's material may leave the secret system. Extendable — e.g. a
 * future "reveal-once". */
export type SecretVisibility = "write-only" | "readable";

/**
 * A named credential-refresh strategy a secret runs in its own trusted DO
 * code — one shared implementation per protocol instead of a worker copied
 * into every secret. Client credentials come from the secret's own material
 * (`"material"`, the bring-your-own-app case) or a platform config reference
 * (built-ins). Exchange endpoints must fall within the secret's pinned egress
 * hosts, so refresh preserves the cell invariant: bytes only ever leave toward
 * pinned hosts.
 */
export type SecretRefresh =
  | {
      kind: "oauth-refresh-token";
      /** RFC 6749 refresh_token grant target (e.g. the provider's /token URL).
       * Its origin must be within the secret's pinned egress hosts. */
      tokenEndpoint: string;
      /** Where the Basic client credential comes from: `"material"` reads
       * clientId/clientSecret fields of this secret's own material. */
      clientCreds: PlatformCredsRef | "material";
    }
  | {
      kind: "github-app-installation";
      /** GitHub API origin (or a stand-in in e2e). Its origin must be within
       * the secret's pinned egress hosts. */
      apiBase: string;
      /** The App id — the JWT issuer (public). */
      appId: string;
      /** The installation this connection acts as (public — it is the
       * connection's external id, not secret material). */
      installationId: string;
      /** Where the App's RS256 private key comes from: `"material"` reads the
       * privateKey field of this secret's own material (bring-your-own-App). */
      privateKey: PlatformCredsRef | "material";
    }
  | {
      kind: "waitrose-session";
      /** The Waitrose GraphQL endpoint (or a stand-in in e2e) the `NewSession`
       * mutation is POSTed to. Its origin must be within the secret's pinned
       * egress hosts. Waitrose has no token-refresh grant — re-login IS the
       * refresh — so this strategy re-runs the login with `username`/`password`
       * from this secret's own material and stores the returned `accessToken`.
       * Material-only by nature: a Waitrose account is always the user's own. */
      graphqlUrl: string;
    };

/** Fields shared by every dynamic worker ref (stateless and stateful): the
 * itx scope `path` the worker binds to and the declarative `source` it is
 * built from. */
export type DynamicWorkerRefBase = {
  /**
   * itx scope path for the worker's `env.ITX` binding and for stateful worker
   * Durable Object names. This is intentionally not the mounted capability path:
   * one worker can be mounted at `db`, `counter`, etc. while all events still
   * belong to the host stream path.
   */
  path: string;
  source: DynamicWorkerSource;
};

/** A workspace's stored configuration: the mount OVERLAY table, keyed by mount path. */
export type WorkspaceConfig = WorkspaceProcessorState["config"];

/** Ephemeral cursor presence for one session: who has a caret where, in the
 * sender's head coordinates. In-memory only — an eviction loses it and
 * clients re-announce on their next throttle tick — delivered on the wait()
 * long-poll when the generation advanced past the client's cursor. */
export type CollabPresence = {
  clients: { anchor: number; at: number; clientId: string; head: number }[];
  generation: number;
};

/** Per-mount changes plus the unmounted local scratch (never committable). */
export type WorkspaceStatus = {
  mounts: {
    changes: WorkspaceChange[];
    path: string;
    policy: "commit-to-main" | "read-only";
    repoPath: string;
  }[];
  unmounted: WorkspaceChange[];
};

/** Input to `WorkspaceGit.commit` — one mount's changes become one commit on its repo's main. */
export type WorkspaceCommitInput = {
  author?: { email: string; name: string };
  message: string;
  /** The mount to commit (its mount path). Optional when exactly one mount is dirty. */
  scope?: string;
};

/** Result of `WorkspaceGit.commit` — the commit landed on the scoped mount's repo main. */
export type WorkspaceCommitResult = {
  branch: string;
  /** Committed paths, spelled as absolute WORKSPACE paths (mount point included). */
  changedPaths: string[];
  commitOid: string;
  /** The mount the commit was scoped to (its workspace path). */
  mount: string;
  repoPath: string;
};

/** Input to `WorkspaceGit.log` — one mount's repo history. */
export type WorkspaceGitLogInput = {
  limit?: number;
  /** The mount to read (its mount path). Optional when the table has exactly one mount. */
  scope?: string;
};

/** One commit returned by `WorkspaceGit.log` (a mounted repo's main history). */
export type WorkspaceGitLogEntry = {
  author: { email: string; name: string };
  message: string;
  oid: string;
  /** Epoch milliseconds. */
  timestamp: number;
};

/** Delivery progress and retry details shared by every live callback connection. */
type ConnectionRuntimeDetails = {
  startedAt: string;
  deliveredThroughOffset: number;
  lag: number;
  batchesSent: number;
  eventsSent: number;
  bytesSent: number;
  lastDeliveredAt?: string;
  completionLatencyMs?: LatencyStats;
  pingRttMs?: LatencyStats;
  openedBy?: ConnectionOpenerDescriptor;
  hasPendingDelivery: boolean;
  pendingDeliveryStartedAt?: string;
  pendingDeliveryDeadlineAt?: string;
};

/** Serializable summary of a {@link LatencyRing}; `null` until a sample exists. */
export type LatencyStats = {
  /** Most recent sample (ms). */
  last: number;
  p50: number;
  p95: number;
  /** Samples currently in the ring (caps at the ring size). */
  samples: number;
  /** Epoch ms of the most recent sample. */
  lastAt: number;
};

/**
 * One direction's throughput report: a responsive trailing-5s rate (the
 * number UIs show), the full-minute totals, and the raw 1s series for graphs.
 */
export type ThroughputReport = {
  /** Events per second over the trailing 5 seconds. */
  perSecond5s: number;
  /** Payload bytes per second over the trailing 5 seconds. */
  bytesPerSecond5s: number;
  lastMinute: MinuteWindow;
  series: ThroughputSeries;
};

/**
 * One-shot acknowledgement capability owned by a single durable wake batch.
 *
 * It is deliberately independent of the callback call's return value. A
 * processor may append back to the stream that delivered the batch; making
 * the stream await that return value can make two Durable Objects wait for
 * each other forever.
 */
export type ReportStreamWakeDeliveryResult = (result: StreamWakeDeliveryResult) => unknown;

/** One Cloudflare Images transform step (width, height, fit, rotate, …),
 * passed through to the Images binding verbatim. */
export type CfImageTransformOptions = { [x: string]: unknown };

/** Placement options for one overlay draw in a Cloudflare Images transform
 * (opacity, repeat, top/left, …), passed through to the Images binding
 * verbatim. */
export type CfImageDrawOptions = { [x: string]: unknown };

/** Output encoding for a Cloudflare Images transform: the target `format`
 * (e.g. "image/webp") plus pass-through options such as quality. */
export type CfImageOutputOptions = { format: string } & Record<string, unknown>;

/** Transform options for a Media Transformations video call (width, height,
 * fit, trim, …), passed through to the binding verbatim. */
export type CfVideoTransformOptions = { [x: string]: unknown };

/** Output selection for a video transform: `mode` picks a video, spritesheet,
 * single frame, or audio track; other options pass through to the binding. */
export type CfVideoOutputOptions = {
  mode: "video" | "spritesheet" | "frame" | "audio";
} & Record<string, unknown>;

/**
 * A reference to a deployment-owned platform credential, resolved from typed
 * AppConfig in trusted platform code — never stored in project material, never
 * readable. Each known config path carries its own allowed-origin list
 * (platform-secrets.ts), so a credential can only ever be sent to the hosts it
 * belongs to, no matter who configured the reference.
 */
export type PlatformCredsRef = { platform: string };

/**
 * One direct worker-bundler call. The wrapper names deliberately match the
 * upstream functions; OS resolves the repo-aware `files` value, applies the
 * deployment-specific `iterate` package pin, and caches the returned build.
 */
export type DynamicWorkerSource =
  | { createApp: WorkerBundlerCreateAppOptions }
  | { createWorker: WorkerBundlerCreateWorkerOptions };

/**
 * One overlay change: a local file that shadows a mount file ("modified" —
 * shadowed, not content-diffed), one the mount does not have ("added"), or a
 * mount file hidden by a local delete ("deleted").
 */
export type WorkspaceChange = {
  change: "added" | "deleted" | "modified";
  path: string;
};

/** Serializable identity of the caller that opened a connection. */
export type ConnectionOpenerDescriptor = {
  description?: string | undefined;
  user?:
    | {
        id?: string | undefined;
        email: string;
        name?: string | undefined;
        picture?: string | undefined;
      }
    | undefined;
  processor?:
    | {
        announcement: {
          slug: string;
          version: string;
          description: string;
          consumes: string[];
          emits: string[];
          ownedEvents: { type: string; description?: string | undefined }[];
        };
      }
    | undefined;
};

/** One rolling-minute throughput window. */
export type MinuteWindow = {
  /** Events in the last 60 seconds. */
  count: number;
  /** Payload bytes in the last 60 seconds. */
  bytes: number;
  /** `count / 60` — the "events/s over the last minute" number. */
  perSecond: number;
};

/** Per-second buckets over the trailing minute, oldest→newest, length 60. */
export type ThroughputSeries = {
  counts: number[];
  bytes: number[];
};

/** The hosted processor's final result for one durable wake delivery. */
export type StreamWakeDeliveryResult =
  | { outcome: "ok" }
  | { outcome: "error"; error: StreamWakeDeliveryError };

/** Serializable `createApp` input. The generated browser bundles and explicit
 * text assets are retained in the host and served by worker-bundler's own
 * asset handler. ArrayBuffer assets and the esbuild plugin callback are the
 * only upstream inputs omitted from this data-only boundary. */
export type WorkerBundlerCreateAppOptions = WorkerBundlerOptions & {
  assetConfig?: WorkerBundlerAssetConfig;
  assets?: Record<string, string>;
  client?: string | string[];
  files: WorkerFileSource;
  server?: string;
};

/** Serializable `createWorker` input. `files` is repo-aware; after resolving
 * it, OS passes the resulting path-to-source map to worker-bundler unchanged.
 * The plugin callback and custom `FileSystem` variants cannot cross Workers
 * RPC, so those are the only upstream inputs omitted here. */
export type WorkerBundlerCreateWorkerOptions = WorkerBundlerOptions & {
  files: WorkerFileSource;
  entryPoint?: string;
  virtualModules?: Record<string, string>;
};

/**
 * Serializable failure reported after a durable wake delivery finishes.
 *
 * The result crosses an independent one-way RPC hop, so preserve the lifecycle
 * flags and ITX call correlation that distinguish and locate failures. Error
 * prototypes and arbitrary properties do not survive that hop reliably.
 */
export type StreamWakeDeliveryError = {
  name: string;
  message: string;
  /** Wide-log ID of the failed ITX call, when the failure crossed that boundary. */
  itxCallId?: string;
  durableObjectReset?: true;
  overloaded?: true;
  retryable?: true;
};

/**
 * The serializable `@cloudflare/worker-bundler` options shared by
 * `createWorker` and `createApp`.
 *
 * These fields are passed through unchanged. The method-specific types below
 * replace only `files` with a repo-aware value and omit callbacks that cannot
 * cross the isolated bundler Worker's RPC boundary.
 */
export type WorkerBundlerOptions = {
  bundle?: boolean;
  conditions?: string[];
  define?: Record<string, string>;
  externals?: string[];
  jsx?: "transform" | "preserve" | "automatic";
  jsxImportSource?: string;
  loader?: Record<string, WorkerBundlerLoader>;
  minify?: boolean;
  registry?: string;
  sourcemap?: boolean;
  target?: string;
};

/** JSON-safe `AssetConfig` accepted by worker-bundler's asset handler. */
export type WorkerBundlerAssetConfig = {
  headers?: Record<string, { set?: Record<string, string>; unset?: string[] }>;
  html_handling?: "auto-trailing-slash" | "force-trailing-slash" | "drop-trailing-slash" | "none";
  not_found_handling?: "single-page-application" | "404-page" | "none";
  redirects?: {
    dynamic?: Record<string, { status: number; to: string }>;
    static?: Record<string, { status: number; to: string }>;
  };
};

/**
 * Where a dynamic worker's source files come from.
 *
 * `inline` supplies the file map directly — the primitive behind run-script and
 * worker-backed provided capabilities where the caller hands over a small
 * TypeScript entry file, helpers, and optionally a `package.json`. `repo` names
 * a project repo snapshot: a branch (late-bound, so future commits affect the
 * next use) or a pinned commit. The whole snapshot is passed through by
 * default; optional include/exclude glob masks let callers narrow it.
 */
export type WorkerFileSource =
  | {
      type: "inline";
      files: Record<string, string>;
    }
  | {
      type: "repo";
      repoPath: string;
      /**
       * Defaults to the repo's default branch when omitted. A pinned commit
       * may name the branch it lives on — clones are single-branch, so an
       * off-default-branch commit is unreachable without it.
       */
      ref?: { branch: string } | { commitOid: string; branch?: string };
      include?: string[];
      exclude?: string[];
    };

/** Portable loader names accepted by `@cloudflare/worker-bundler`. */
export type WorkerBundlerLoader =
  | "js"
  | "jsx"
  | "ts"
  | "tsx"
  | "json"
